                        visible_size.x,
                        track_length.x,
                        scrollbar.min_thumb_length,
                        scroll_area.0.x,
                    );
                    (
                        Vec2::new(thumb_size, track_length.y),
                        Vec2::new(thumb_pos + 0.5 * (thumb_size - track_length.x), 0.),
